// Throwaway: drive headless Chrome via CDP. Usage: node cdp.mjs <url> <steps.json> [js-disabled]
import { spawn } from 'node:child_process';
import { writeFileSync, readFileSync } from 'node:fs';
const [url, stepsFile, nojs] = process.argv.slice(2);
const steps = JSON.parse(readFileSync(stepsFile, 'utf8'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  ['--headless=new', '--remote-debugging-port=9333', '--user-data-dir=/tmp/actcheck/profile', '--window-size=1100,900', 'about:blank']);
await new Promise(r => setTimeout(r, 1500));
const targets = await (await fetch('http://127.0.0.1:9333/json')).json();
const ws = new WebSocket(targets.find(t => t.type === 'page').webSocketDebuggerUrl);
await new Promise(r => ws.onopen = r);
let id = 0; const pending = {};
ws.onmessage = m => { const d = JSON.parse(m.data); if (pending[d.id]) { pending[d.id](d); delete pending[d.id]; } };
const send = (method, params = {}) => new Promise(r => { pending[++id] = r; ws.send(JSON.stringify({ id, method, params })); });
const ev = async expr => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result?.result?.value;
if (nojs) await send('Emulation.setScriptExecutionDisabled', { value: true });
await send('Page.enable');
await send('Page.navigate', { url }); await new Promise(r => setTimeout(r, 1000));
for (const s of steps) {
  if (s.key) {
    const codes = { Tab: 9, ArrowDown: 40, ArrowUp: 38, Enter: 13, ' ': 32 };
    for (const type of ['rawKeyDown', 'keyUp']) await send('Input.dispatchKeyEvent', { type, key: s.key, code: s.key, windowsVirtualKeyCode: codes[s.key], ...(s.shift ? { modifiers: 8 } : {}) });
    await new Promise(r => setTimeout(r, 150));
  }
  if (s.width) { await send('Emulation.setDeviceMetricsOverride', { width: s.width, height: 900, deviceScaleFactor: 1, mobile: false }); await new Promise(r => setTimeout(r, 300)); }
  if (s.eval) console.log(s.label || s.eval, '=>', JSON.stringify(await ev(s.eval)));
  if (s.shot) { const d = await send('Page.captureScreenshot', {}); writeFileSync(s.shot, Buffer.from(d.result.data, 'base64')); console.log('screenshot', s.shot); }
}
ws.close(); chrome.kill();
EOF
